import { toIsoTimestamp } from \"@/types/common\";
import type { BillingInterval, Subscription } from \"@/types/billing\";
import type { IsoTimestamp } from \"@/types/common\";

const DAY_MS = 86_400_000;

/** UTC calendar arithmetic, preserving time and carrying clamped days forward. */
export function periodEnd(start: IsoTimestamp, interval: BillingInterval): IsoTimestamp {
  const end = new Date(start);
  const day = end.getUTCDate();
  end.setUTCDate(1);
  end.setUTCMonth(end.getUTCMonth() + (interval === \"annual\" ? 12 : 1));
  const lastDay = new Date(Date.UTC(end.getUTCFullYear(), end.getUTCMonth() + 1, 0)).getUTCDate();
  end.setUTCDate(Math.min(day, lastDay));
  return toIsoTimestamp(end);
}

export function prorate(amountCents: number, subscription: Subscription, now: Date): number {
  const end = new Date(subscription.currentPeriodEnd).getTime();
  const start = new Date(subscription.currentPeriodStart).getTime();
  const days = Math.max(1, Math.round((end - start) / DAY_MS));
  const remaining = Math.max(0, Math.ceil((end - now.getTime()) / DAY_MS));
  return Math.floor(amountCents * remaining / days);
}
