import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from \"vitest\";
import { eq } from \"drizzle-orm\";
import { subscribe } from \"@/lib/event-bus\";
import { getDb, organizations, subscriptions, activityEvents, notifications } from \"@/server/db\";
import { runBillingRenewalJob } from \"@/server/jobs/billing-renewal-job\";
import * as subscriptionRepo from \"@/server/repositories/subscription-repository\";
import * as invoiceRepo from \"@/server/repositories/invoice-repository\";
import { registerActivityListeners } from \"@/server/services/activity-service\";
import * as billing from \"@/server/services/billing-service\";
import \"@/server/services/notification-service\";
import { periodEnd } from \"@/server/services/billing-period\";
import { toIsoTimestamp } from \"@/types/common\";
import { createTenant, useTemporaryDatabase } from \"../server/_support/fixtures\";
import type { Subscription } from \"@/types/billing\";
import type { OrgId } from \"@/types/common\";

let cleanup: () => void;
let offAudit: () => void;
beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  offAudit = registerActivityListeners();
});
afterEach(() => vi.useRealTimers());
afterAll(() => { offAudit(); cleanup(); });

function setPeriod(orgId: OrgId, patch: Partial<Subscription> = {}) {
  getDb().update(subscriptions).set({
    status: \"active\", currentPeriodStart: \"2026-01-01T10:00:00.000Z\",
    currentPeriodEnd: \"2026-02-01T10:00:00.000Z\", ...patch,
  }).where(eq(subscriptions.orgId, orgId)).run();
}

describe(\"billing periods\", () => {
  it(\"clamps monthly and annual boundaries and preserves the time\", () => {
    const feb = periodEnd(toIsoTimestamp(new Date(\"2025-01-31T14:12:13.456Z\")), \"monthly\");
    expect(feb).toBe(\"2025-02-28T14:12:13.456Z\");
    expect(periodEnd(feb, \"monthly\")).toBe(\"2025-03-28T14:12:13.456Z\");
    expect(periodEnd(toIsoTimestamp(new Date(\"2024-02-29T09:00:00Z\")), \"annual\"))
      .toBe(\"2025-02-28T09:00:00.000Z\");
  });

  it(\"catches up every paid period, announces each once, and replays without changes\", async () => {
    const tenant = await createTenant(\"renewal-paid\", \"starter\");
    setPeriod(tenant.org.id, { seats: 2 });
    const seen: string[] = [];
    const off = subscribe(\"billing.invoice_issued\", (event) => { seen.push(event.invoiceId); });
    const now = new Date(\"2026-04-01T10:00:00Z\");
    await runBillingRenewalJob(now);
    await runBillingRenewalJob(now);
    off();
    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices).toHaveLength(3);
    expect(new Set(invoices.map((invoice) => invoice.number)).size).toBe(3);
    expect(invoices.map((invoice) => invoice.periodStart)).toEqual([
      \"2026-04-01T10:00:00.000Z\", \"2026-03-01T10:00:00.000Z\", \"2026-02-01T10:00:00.000Z\",
    ]);
    expect(invoices.every((invoice) => invoice.amountCents === 1800 && invoice.currency === \"usd\" && invoice.paidAt === null)).toBe(true);
    expect(seen).toHaveLength(3);
    const audit = getDb().select().from(activityEvents).where(eq(activityEvents.orgId, tenant.org.id)).all();
    expect(audit).toHaveLength(3);
    expect(audit.every((event) => event.action === \"billing.invoice_issued\" && event.subjectKind === \"subscription\" && event.subjectId === tenant.org.id)).toBe(true);
    const notices = getDb().select().from(notifications).where(eq(notifications.orgId, tenant.org.id)).all();
    expect(notices).toHaveLength(3);
    expect(notices.every((notice) => notice.kind === \"invoice_issued\" && notice.recipientId === tenant.userIds.owner)).toBe(true);
  });

  it(\"ignores archived, trialing, past-due and not-yet-canceled subscriptions\", async () => {
    for (const status of [\"trialing\", \"past_due\", \"canceled\"] as const) {
      const tenant = await createTenant("'`renewal-ignore-${status}`, "growth");
      setPeriod(tenant.org.id, { status, cancelAt: toIsoTimestamp(new Date("2026-06-01Z")) });
      const before = await subscriptionRepo.findSubscription(tenant.org.id);
      await runBillingRenewalJob(new Date("2026-04-01Z"));
      expect(await subscriptionRepo.findSubscription(tenant.org.id)).toEqual(before);
      expect(await invoiceRepo.listInvoices(tenant.org.id)).toEqual([]);
    }
    const archived = await createTenant("renewal-archived", "growth");
    setPeriod(archived.org.id);
    getDb().update(organizations).set({ archivedAt: "2026-01-01T00:00:00Z" }).where(eq(organizations.id, archived.org.id)).run();
