/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const now = new Date();

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const change = subscriptionRepo.mutateSubscription(input.orgId, now, (current) => {
    const patch: subscriptionRepo.SubscriptionPatch = {
      plan: input.plan, interval: input.interval,
      status: current.status === "trialing" ? "trialing" : "active", cancelAt: null,
    };
    let amountCents = 0;
    if (current.status !== "trialing" && current.plan === "free" && input.plan !== "free") {
      patch.currentPeriodStart = toIsoTimestamp(now);
      patch.currentPeriodEnd = periodEnd(patch.currentPeriodStart, input.interval);
      amountCents = fullPeriodCharge(input.plan, current.seats, input.interval);
    } else if (current.status === "active" && current.plan !== "free" && input.plan !== "free") {
      const difference = getPlanLimits(input.plan).priceCentsPerSeatMonthly -
        getPlanLimits(current.plan).priceCentsPerSeatMonthly;
      amountCents = prorate(Math.max(0, difference) * current.seats *
        (current.interval === "annual" ? 12 : 1), current, now);
    }
    return { patch, charges: [{ amountCents,
      periodStart: patch.currentPeriodStart ?? current.currentPeriodStart,
      periodEnd: patch.currentPeriodEnd ?? current.currentPeriodEnd,
    }] };
  })!;
  await publishInvoices(change.invoices, now);

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: change.previous.plan,
    to: input.plan,
  });

  return change.subscription;
}

export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const now = new Date();
  const plan = await planFor(input.orgId);

  if (input.seats > getLimit(plan, "seats")) {
    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
  }

  const change = subscriptionRepo.mutateSubscription(input.orgId, now, (current) => {
    const amountCents = current.status === "active" && current.plan !== "free"
      ? prorate(fullPeriodCharge(current.plan, Math.max(0, input.seats - current.seats), current.interval), current, now)
      : 0;
    return { patch: { seats: input.seats }, charges: [{ amountCents,
      periodStart: current.currentPeriodStart, periodEnd: current.currentPeriodEnd,
    }] };
  })!;
  await publishInvoices(change.invoices, now);
  return change.subscription;
}

/** Cancels at period end by default; `cancelImmediately` ends it now. */
export async function cancelSubscription(
  actor: Actor,
  input: CancelSubscriptionInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  return subscriptionRepo.cancelSubscription(
    input.orgId,
    input.cancelImmediately
      ? toIsoTimestamp(new Date())
      : subscription.currentPeriodEnd,
  );
}

export async function listInvoices(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly Invoice[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:manage_billing", billingResource(orgId));
  return invoiceRepo.listInvoices(orgId);
}

/**
 * The subscription row is the authority on which plan an org is on; the
 * denormalised `organizations.plan` column is only a display convenience, so
 * every quota decision reads the subscription first.
 */
async function planFor(orgId: OrgId): Promise<PlanId> {
  const subscription = await subscriptionRepo.findSubscription(orgId);
import { emit } from "@/lib/event-bus";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { fullPeriodCharge, publishInvoices } from "@/server/services/billing-service";
import { periodEnd } from "@/server/services/billing-period";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "./types";

export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    for (const candidate of await subscriptionRepo.listLiveSubscriptions()) {
      const change = subscriptionRepo.mutateSubscription(candidate.orgId, now, (current) => {
        if (current.status === "canceled") {
          if (current.cancelAt === null || new Date(current.cancelAt) > now) return null;
          let start = current.cancelAt;
          let end = periodEnd(start, "monthly");
          while (new Date(end) <= now) {
            start = end;
            end = periodEnd(start, "monthly");
          }
          return { patch: {
            plan: "free", status: "active", interval: "monthly", cancelAt: null,
            currentPeriodStart: start, currentPeriodEnd: end,
          }, charges: [] };
        }
        if (current.status !== "active" || new Date(current.currentPeriodEnd) > now) return null;
        let start = current.currentPeriodStart;
        let end = current.currentPeriodEnd;
        const charges: subscriptionRepo.PeriodCharge[] = [];
        while (new Date(end) <= now) {
          start = end;
          end = periodEnd(start, current.interval);
          if (current.plan !== "free") charges.push({
            amountCents: fullPeriodCharge(current.plan, current.seats, current.interval),
            periodStart: start, periodEnd: end,
          });
        }
        return { patch: { currentPeriodStart: start, currentPeriodEnd: end }, charges };
      });
      if (!change) continue;
      await publishInvoices(change.invoices, now);
      if (change.previous.status === "canceled") {
        await emit("billing.plan_changed", {
          orgId: candidate.orgId, actorId: null, occurredAt: toIsoTimestamp(now),
          from: change.previous.plan, to: "free",
        });
      }
      result.processed += 1;
    }
  });
}
